macro.command:
if(args[0].macroPass === "isHit") {
    if(workflow.activity.actionType !== "mwak" && workflow.activity.actionType !== "msak") return;
    let target = workflow.token;
    let measuredDistance = MidiQOL.computeDistance(token,target, {wallsBlock: true, includeCover: true});
    if(measuredDistance === -1 || measuredDistance > 5) return;

    let damageRoll = await new CONFIG.Dice.DamageRoll(`1d10`, {}, {type: "fire", properties: ["mgc"]}).evaluate();
    await MidiQOL.displayDSNForRoll(damageRoll, 'damageRoll');

    const itemData = {
        flags: {autoanimations: {isEnabled: false, version: 5}},
        name: "Fire Form - Damage (Fire)",
        type: "feat",
        img: macroItem.img
    }

    await new MidiQOL.DamageOnlyWorkflow(actor, token, damageRoll.total, "fire", target ? [target] : [], damageRoll, {itemData: itemData, flavor: "Fire Form - Damage (Fire)"});
}

if(args[0] === "on") {
    let effectOriginActor = await fromUuid(args[1]);
    let effectOriginToken = await MidiQOL.tokenForActor(effectOriginActor);
    let checkEffect = actor.appliedEffects.some(e => e.name === "Ignition");
    if(checkEffect) return;
    let effectData = [{
      "origin": item.uuid,
      "duration": { value: 99999, units: "seconds" },
      "disabled": false,
      "name": "Ignition",
      "img": item.img,
      system: { changes: [
        {
          "key": "flags.midi-qol.OverTime",
          type: "custom",
          "value": "turn=start,saveCount=1,damageRoll=1d10,damageType=fire,name=Ignition",
          "priority": 20
        }
      ] },
      "transfer": false
    }];

    await MidiQOL.socket().executeAsGM("createEffects", { actorUuid: actor.uuid, effects: effectData });

    let damageRoll = await new CONFIG.Dice.DamageRoll(`1d10`, {}, {type: "fire", properties: ["mgc"]}).evaluate();
    await MidiQOL.displayDSNForRoll(damageRoll, 'damageRoll');

    const itemData = {
        flags: {autoanimations: {isEnabled: false, version: 5}},
        name: "Fire Form - Damage (Fire)",
        type: "feat",
        img: item.img
    }

    await new MidiQOL.DamageOnlyWorkflow(effectOriginActor, effectOriginToken, damageRoll.total, "fire", token ? [token] : [], damageRoll, {itemData: itemData, flavor: "Fire Form - Damage (Fire)"});
}
